pub(crate) struct BaseTriangleSetup {\n    pub ux: f32,\n    pub uy: f32,\n    pub vx: f32,\n    pub vy: f32,\n    pub nz: f32,\n    pub inv_nz: f32,\n    pub dz_dx: f32,\n}\n\nimpl BaseTriangleSetup {\n    #[inline(always)]\n    pub(crate) fn compute(p0: ScreenPoint, p1: ScreenPoint, p2: ScreenPoint) -> Self {\n        let ux = (i64::from(p1.x) - i64::from(p0.x)) as f32;\n        let uy = (i64::from(p1.y) - i64::from(p0.y)) as f32;\n        let uz = p1.z - p0.z;\n        let vx = (i64::from(p2.x) - i64::from(p0.x)) as f32;\n        let vy = (i64::from(p2.y) - i64::from(p0.y)) as f32;\n        let vz = p2.z - p0.z;\n        let nz = ux * vy - uy * vx;\n        let inv_nz = if nz.abs() > 0.0001 { -1.0 / nz } else { 0.0 };\n        let nx_z = uy * vz - uz * vy;\n        let dz_dx = nx_z * inv_nz;\n        Self {\n            ux,\n            uy,\n            vx,\n            vy,\n            nz,\n            inv_nz,\n            dz_dx,\n        }\n    }\n\n    #[inline(always)]\n    pub(crate) fn calc_dx(&self, du: f32, dv: f32) -> f32 {\n        (self.uy * dv - du * self.vy) * self.inv_nz\n    }\n\n    #[inline(always)]\n    pub(crate) fn calc_dy(&self, du: f32, dv: f32) -> f32 {' crates/abrash-render/src/rasterizer/core.rs
